const [auth,setAuth]=useState<any>(null),[data,setData]=useState<any>(empty),[period,setPeriod]=useState('month'),[range,setRange]=useState(dates('month')),[busy,setBusy]=useState(false),[loading,setLoading]=useState(true),[error,setError]=useState(''),[toast,setToast]=useState(''),[modal,setModal]=useState<any>(null),[search,setSearch]=useState(''),[mobile,setMobile]=useState(false),[report,setReport]=useState('Monthly Sales Report');
const {page,setPage,selected,setSelected}=usePageNavigation('admin',navigationPages,'dashboard',!!auth?.signedIn&&auth.user?.role!=='client'&&auth.user?.role!=='programmer'&&auth.user?.role!=='manager'&&auth.user?.role!=='sales'&&auth.user?.role!=='employee');
const [connected,setConnected]=useState(true),[local,setLocal]=useState<any>({enabled:false,unlocked:false,queue:[]}),[syncError,setSyncError]=useState('');const syncing=useRef(false);
function acceptLocal(v:any){setData(v.data);setLocal({enabled:true,unlocked:true,...v});}
async function synchronize(){if(syncing.current)return;syncing.current=true;try{const v=await offline.syncOffline();acceptLocal(v);setSyncError('');setConnected(true);}catch(e:any){setSyncError(e.message);const v=await offline.offlineView();acceptLocal(v);if(e.status===401)setAuth((a:any)=>({...a,signedIn:false,setup:false,offline:false}));if(!e.status)setConnected(false);}finally{syncing.current=false;}}
async function load(){setLoading(true);try{const info=await offline.offlineInfo().catch(()=>({enabled:false,unlocked:false}));if(info.unlocked){if(navigator.onLine)await synchronize();else{acceptLocal(await offline.offlineView());setConnected(false);}return;}const r=await fetch('/api/data',{cache:'no-store'});const b:any=await r.json();if(!r.ok){if(r.status===401)setAuth((a:any)=>({...a,signedIn:false}));throw new Error(b.error);}setData(b);setError('');}catch(e:any){setError(e.message);}finally{setLoading(false);}}
useEffect(()=>{let cancelled=false;async function start(){const info=await offline.offlineInfo().catch(()=>({enabled:false,unlocked:false,email:''}));if(cancelled)return;setLocal({...info,queue:[]});setConnected(navigator.onLine);try{if(!navigator.onLine)throw new Error('offline');const r=await fetch('/api/auth',{cache:'no-store'});const b:any=await r.json();if(!r.ok&&!b.platform)throw new Error('تعذر الاتصال');if(cancelled)return;setAuth(b);if(b.signedIn&&['programmer','manager','sales','employee','client'].includes(b.user?.role)){offline.lockOffline();setLocal({enabled:false,unlocked:false,queue:[]});setLoading(false);}else if(b.signedIn)await load();else setLoading(false);}catch{if(!cancelled){setAuth({signedIn:false,setup:false,platform:true,email:info.email||'',offline:true,error:info.enabled?'':'يلزم فتح التطبيق وتفعيل النسخة المحلية أولًا أثناء الاتصال بالإنترنت'});setLoading(false);setConnected(false);}}}start();return()=>{cancelled=true;};},[]);
useEffect(()=>{const online=()=>{setConnected(true);offline.offlineInfo().then(i=>{if(i.unlocked)synchronize();});};const lost=()=>setConnected(false);window.addEventListener('online',online);window.addEventListener('offline',lost);const timer=setInterval(()=>{if(navigator.onLine)offline.offlineInfo().then(i=>{if(i.unlocked)synchronize();});},60000);return()=>{window.removeEventListener('online',online);window.removeEventListener('offline',lost);clearInterval(timer);};},[]);
useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(t);},[toast]);
const config=[...data.settings].filter((s:any)=>s.effective<=today()).sort((a:any,b:any)=>a.effective.localeCompare(b.effective)).at(-1)||data.settings[0];
