const expensesList=filtered(data.expenses.filter((e:any)=>e.date>=range.from&&e.date<=range.to).sort((a:any,b:any)=>b.date.localeCompare(a.date)),['name','category','notes']);
const graphFrom=range.from;
const trend=monthly(data,graphFrom,range.to).map(x=>({name:new Date(x.month+'-01T12:00:00Z').toLocaleDateString(locale(),{month:'short'}),sales:x.revenue/100,expenses:x.expense/100,profit:x.profit/100,marketing:x.marketing/100,projects:x.count}));
const periodTrend=monthly(data,range.from,range.to).map(x=>({name:new Date(x.month+'-01T12:00:00Z').toLocaleDateString(locale(),{month:'short'}),sales:x.revenue/100,expenses:x.expense/100,profit:x.profit/100,marketing:x.marketing/100,projects:x.count}));
async function mutate(b:any){setBusy(true);setError('');try{const info=await offline.offlineInfo().catch(()=>({unlocked:false}));if(info.unlocked){acceptLocal(await offline.queueMutation(b));setModal(null);if(b.action==='delete')setSelected(null);setToast('تم الحفظ على الجهاز');if(navigator.onLine)await synchronize();return;}if(!navigator.onLine)throw new Error('فعّل النسخة المحلية أثناء الاتصال بالإنترنت أولًا');const r=await fetch('/api/data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...b,requestId:crypto.randomUUID()})});const result:any=await r.json();if(!r.ok)throw new Error(result.error);setModal(null);setToast(b.action==='delete'?'تم الحذف وتحديث الحسابات':'تم الحفظ بنجاح');if(b.action==='delete')setSelected(null);await load();}catch(e:any){setError(e.message);}finally{setBusy(false);}}
function open(type:string,values:any={}){setError('');setModal({type,values});}
function edit(type:string,row:any){const sourceTables:Record<string,string>={client:'clients',sale:'sales',payment:'payments',expense:'expenses',design:'design_tasks',employee:'employees',task:'tasks'};row=data[sourceTables[type]]?.find((item:any)=>item.id===row.id)||row;let v={...row};if(type==='sale'){const p=projects.find((p:any)=>p.sale_id===row.id);v={...v,clientName:data.clients.find((c:any)=>c.id===row.client_id)?.name||'',amount:row.amount/100,domainPrice:(p?.domainPrice||0)/100,start:p?.start||row.date,paidTotal:data.payments.filter((x:any)=>x.sale_id===row.id).reduce((n:number,x:any)=>n+x.amount,0)/100,responsible:p?.responsible||''};}if(type==='payment')v={...v,saleId:row.sale_id,amount:row.amount/100};if(type==='expense'){const d=data.design_tasks.find((d:any)=>d.expense_id===row.id);if(d)return edit('design',d);v={...v,amount:row.amount/100,projectId:row.project_id||'',paidDate:row.paid_date||''};}if(type==='design')v={...v,projectId:row.project_id,price:row.price/100,paidDate:data.expenses.find((e:any)=>e.id===row.expense_id)?.paid_date||''};if(type==='employee')v={...v,amount:row.amount/100,contractType:row.type,startMonth:row.start_month};if(type==='task')v={...v,projectId:row.project_id};open(type,v);}

function removeButton(type:string,row:any){return <button className="text-btn negative" disabled={busy} onClick={()=>open('delete',{id:row.id,recordType:type,name:row.name||row.effective||row.date||'السجل'})}>{t("حذف")}</button>;}
const deleteNotes:Record<string,string>={client:'سيتم حذف العميل وكل مبيعاته ومشاريعه ودفعاته وتكاليفه ومهامه.',sale:'سيتم حذف البيع والمشروع المرتبط به وكل دفعاته وتكاليفه ومهامه.',project:'سيتم حذف المشروع وعملية البيع المرتبطة به وكل دفعاته وتكاليفه ومهامه.',expense:'سيُحذف المصروف وعمولته التلقائية إن وجدت، والتصميم المرتبط به إن وجد.',design:'سيُحذف التصميم وتكلفته المرتبطة بالمشروع.',employee:'سيُحذف عضو الفريق ورواتبه المسجلة، ويتوقف تسجيل رواتبه القادمة.',payment:'سيُحذف مبلغ الدفعة من التحصيل ويزيد المتبقي على العميل.',task:'سيتم حذف المهمة.',settings:'سيُحذف تغيير الأسعار ويُستخدم الإعداد السابق. المصروفات المسجلة سابقًا تبقى محفوظة.'};
async function login(e:any){e.preventDefault();setBusy(true);setError('');const b:any=Object.fromEntries(new FormData(e.currentTarget));try{if(!navigator.onLine||auth.offline||b.localOnly==='on'){const v=await offline.unlockOffline(String(b.email),String(b.password));acceptLocal(v);setAuth({signedIn:true,user:{email:v.email,role:'admin'},platform:true,offline:true});setConnected(navigator.onLine);if(navigator.onLine)await synchronize();return;}const r=await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...b,action:auth.setup?'setup':'login',portal:'admin'})});const res:any=await r.json();if(!r.ok)throw new Error(res.error);const authResponse:any=res.user?res:await (await fetch('/api/auth',{cache:'no-store'})).json();const identity=authResponse.user;setAuth({...auth,signedIn:true,user:identity});if(['programmer','manager','sales','employee','client'].includes(identity?.role)){offline.lockOffline();setData(empty);setLocal({enabled:false,unlocked:false,queue:[]});return;}const info=await offline.offlineInfo();if(info.enabled){acceptLocal(await offline.unlockOffline(String(b.email),String(b.password)));await synchronize();}else await load();}catch(e:any){setError(e.message);}finally{setBusy(false);}}
async function logout(){if(navigator.onLine)try{await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'logout'})});}catch{}offline.lockOffline();setData(empty);setLocal((l:any)=>({...l,unlocked:false,queue:[]}));setAuth({...auth,signedIn:false,setup:false,offline:!navigator.onLine});}
async function activateOffline(e:any){e.preventDefault();setBusy(true);setError('');const password=String(new FormData(e.currentTarget).get('password'));try{if(!navigator.onLine)throw new Error('التفعيل الأول يحتاج إنترنت');const email=auth.user?.email||auth.email;const r=await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'login',email,password})});const result:any=await r.json();if(!r.ok)throw new Error(result.error);acceptLocal(await offline.enableOffline(email,password,data));await offline.prepareOfflineShell();acceptLocal(await offline.markShellReady());await synchronize();setModal(null);setToast('النسخة المحلية جاهزة للعمل دون إنترنت');}catch(e:any){setError(e.message);}finally{setBusy(false);}}
async function discardLocal(){setBusy(true);try{acceptLocal(await offline.discardPending());setSyncError('');setModal(null);setToast('تم اعتماد بيانات السيرفر');}catch(e:any){setError(e.message);}finally{setBusy(false);}}
