const reportNames=['Monthly Sales Report','Monthly Expenses Report','Monthly Profit Report','Project Profitability Report','Marketing Report','Outstanding Payments Report','Designer Cost Report'];
const reportLabels=['المبيعات الشهرية','المصروفات الشهرية','الأرباح الشهرية','ربحية المشاريع','تكلفة التسويق','مستحقات العملاء','تكلفة التصميمات'];
function reportData(){const m=monthly(data,range.from,range.to);const dateSales=data.sales.filter((s:any)=>salePeriodDate(data,s)>=range.from&&salePeriodDate(data,s)<=range.to&&s.status!=='ملغي');if(report==='Monthly Sales Report')return{headers:['الشهر','قيمة المبيعات (ج.م)','تحصيل مشاريع الشهر حتى نهايته (ج.م)','دفعات بتاريخ الشهر (ج.م)','مستحقات مبيعات الفترة (ج.م)','عدد المشاريع'],rows:m.map(x=>[x.month,x.revenue/100,x.collected/100,x.periodCollected/100,x.outstanding/100,x.count])};if(report==='Monthly Expenses Report')return{headers:['الشهر',...categories.map(c=>categoryLabels[c]+' (ج.م)'),'الإجمالي (ج.م)'],rows:m.map(x=>[x.month,...categories.map(c=>x.byCategory[c]/100),x.expense/100])};if(report==='Monthly Profit Report')return{headers:['الشهر','المبيعات','المصروفات','صافي الربح','التدفق النقدي','هامش الربح %'],rows:m.map(x=>[x.month,x.revenue/100,x.expense/100,x.profit/100,x.cashFlow/100,Math.round(x.margin*100)/100])};if(report==='Project Profitability Report')return{headers:['المشروع','العميل','القيمة','التكلفة المباشرة','الربح الإجمالي','الحالة'],rows:projects.filter((p:any)=>p.start>=range.from&&p.start<=range.to).map((p:any)=>[p.name,p.client,p.amount/100,p.cost/100,p.profit/100,p.status])};if(report==='Marketing Report')return{headers:['الشهر','الإعلانات','عمولة ميديا باير','إجمالي التسويق'],rows:m.map(x=>[x.month,x.byCategory.Advertising/100,x.byCategory['Media Buyer']/100,x.marketing/100])};if(report==='Outstanding Payments Report')return{headers:['العميل','المشروع','القيمة','المحصل حتى نهاية الفترة','المتبقي'],rows:dateSales.map((s:any)=>{const paid=data.payments.filter((p:any)=>p.sale_id===s.id&&p.date<=range.to).reduce((n:number,p:any)=>n+p.amount,0);return[data.clients.find((c:any)=>c.id===s.client_id)?.name,s.name,s.amount/100,paid/100,(s.amount-paid)/100];}).filter((r:any)=>r[4]>0)};return{headers:['التاريخ','المشروع','التصميم','العدد','سعر التصميم','الإجمالي'],rows:data.design_tasks.filter((d:any)=>d.date>=range.from&&d.date<=range.to).map((d:any)=>[d.date,projects.find((p:any)=>p.id===d.project_id)?.name,d.name,d.count,d.price/100,d.count*d.price/100])};}
const rd=reportData();
function exportReport(type:string){const title=t(reportLabels[reportNames.indexOf(report)]);const headers=rd.headers.map(t);const rows=rd.rows.map((r:any[])=>r.map((x:any,j:number)=>report==='Project Profitability Report'&&j===5?enumText(x):x));try{if(type==='csv')csv(headers,rows,title);if(type==='excel')excel(headers,rows,title);if(type==='pdf')pdf(headers,rows,title,range.from+' '+t('إلى')+' '+range.to);}catch(e:any){setError(e.message);}}
if(!auth)return <div className="loading-screen"><img src="/brand/raqamia-mark.png" width="58" height="80" alt="raqamia tech" style={{borderRadius:10}}/><p>{t("جارٍ فتح raqamia tech…")}</p></div>;
if(!auth.signedIn)return <div className="login"><section className="login-brand"><div className="brand"><img className="brand-logo" src="/brand/raqamia-logo.png" alt="raqamia tech" width="210" height="73"/><small>{t("إدارة الشركة")}</small></div><div><span className="eyebrow">{t("مساحة عملك، بوضوح أكبر")}</span><h1>{t("كل مشروع.")}<br/>{t("كل جنيه.")}<br/><em>{t("في مكان واحد.")}</em></h1><p>{t("تابع مبيعاتك، اعرف تكاليفك، وشاهد الصورة المالية الحقيقية لشركتك.")}</p><div className="login-feature"><ShieldCheck/>{t(" مساحة خاصة وآمنة لإدارة شركتك")}</div></div><small>RAQAMIA TECH BUSINESS WORKSPACE</small></section><section className="login-form"><div className="login-form-inner">{t(languageButton)}<div className="login-mark"><Building2 size={25}/></div><h2>{t(auth.offline?'فتح النسخة المحلية':auth.setup?'إعداد حساب المدير':'مرحبًا بك من جديد')}</h2><p>{t(auth.offline?'أدخل كلمة مرورك لفتح بيانات هذا الجهاز.':auth.setup?'استخدم بريد حسابك وأنشئ كلمة مرور خاصة بالنظام.':'سجّل الدخول للمتابعة إلى مساحة عملك.')}</p>{<form onSubmit={login}><label>{t("البريد الإلكتروني")}<input name="email" type="email" dir="ltr" defaultValue={auth.email} required autoComplete="username"/></label><label>{t("كلمة المرور")}<PasswordField name="password" dir="ltr" minLength={12} maxLength={128} required autoComplete={auth.setup?'new-password':'current-password'} placeholder={t("12 حرفًا على الأقل")}/></label>{local.enabled&&!auth.setup&&<label className="salary-toggle"><input type="checkbox" name="localOnly" defaultChecked={!!auth.offline}/>{t(" فتح نسخة الجهاز")}</label>}{auth.error&&<p className="negative">{t(auth.error)}</p>}{error&&<div role="alert" className="error">{t(error)}</div>}<button disabled={busy} className="btn primary wide">{t(busy?'جارٍ التحقق…':auth.setup?'إنشاء الحساب وفتح النظام':'تسجيل الدخول')}</button></form>}{!auth.setup&&!auth.offline&&<AdminRecoveryLogin/>}<div className="staff-login-links"><a href="/team">{t('دخول الفريق')}</a><a href="/sales">{t('دخول السيلز')}</a><a href="/client">{t('بوابة العميل')}</a></div><div className="login-note"><ShieldCheck size={16}/>{t("حسابات خاصة للمدير والمبرمجين والعملاء")}</div></div></section></div>;
if(auth.user?.role==='client')return <ClientPortal user={auth.user} languageButton={languageButton} onLogout={logout}/>;
if(auth.user?.role==='sales')return <SalesWorkspace user={auth.user} languageButton={languageButton} onLogout={logout}/>;
if(auth.user?.role==='employee')return <StaffEntry portal="team"/>;
if(auth.user?.role==='manager')return <ManagerWorkspace user={auth.user} languageButton={languageButton} onLogout={logout}/>;
